Record IENV (tp : word) (TSD CTX TH sb TOP BOT : Z) (m : mem) : Prop := mkIENV {
  i_tsdi : rw_cells asegs m 1821152 [C1 (b8 1); CB 3 [b8 0; b8 0; b8 0]; C4 (wz 0)];
  i_tp   : rw_cells asegs m (bv_unsigned tp + -88) [C8 (wz TSD)];
  i_tsd  : rw_cells asegs m TSD [C8 (wz CTX)];
  i_ctx  : rw_cells asegs m (CTX + 152) [C8 (wz TH)];
  i_lsan : rw_cells asegs m (bv_unsigned tp + 16) [C4 (wz 0)];
  i_got2 : rw_cells asegs m 0x1b2fd8 [C8 (wz 0x10)];
  i_thr  : rw_cells asegs m TH [C8 (wz CTX)];
  i_tid  : rw_cells asegs m (CTX + 8) [C4 (wz 0)];
  i_init : rw_cells asegs m 1826392 [C1 (b8 1)];
  i_afl  : rw_cells asegs m 2356192 [C1 (b8 0); C1 (b8 1); C1 (b8 0)];
  i_can  : rw_cells asegs m 1821148 [C1 (b8 1)];
  i_got  : rw_cells asegs m 1778520 (map (fun v => C8 (wz v)) AGOT_VALS);
  i_shb  : rw_cells asegs m 1823096 [C8 (wz 2147450880)];
  i_hme  : rw_cells asegs m 1826400 [C8 (wz 140737488355327); C8 (wz 0); C8 (wz 0)];
  i_thresh : rw_cells asegs m 2420000 [C8 (wz 0xffffffffffffffff)];
  i_rms  : rw_cells asegs m 1786752 [C8 (wz 1714080)];
  i_fill : rw_cells asegs m 1812900 [C4 (wz 4096); C4 (wz 0); C4 (wz 0xbe)];
  i_part : rw_cells asegs m 1812941 [C1 (b8 1)];
  i_hooks : rw_cells asegs m 2419776 (repeat (C8 (wz 0)) 10);
  i_inst1 : rw_cells asegs m 1809208 [C8 (wz sb)];
  i_inst2 : rw_cells asegs m 1812792 [C8 (wz (2^40)); C2 (wz 16); C2 (wz 2048); C1 (b8 1); CB 3 [b8 0; b8 0; b8 0]];
  (* [comment removed for export] *)
  i_mcs  : rw_cells asegs m 0x1bde7c [C4 (wz 30)];                 (* [comment removed for export] *)
  i_psc  : rw_cells asegs m 0x24cc20 [C8 (wz 4096)];               (* [comment removed for export] *)
  i_cfu  : rw_cells asegs m (0x24eca8 + 34) [C1 (b8 1)];           (* [comment removed for export] *)
  i_stk  : rw_cells asegs m (TH + 8) [C8 (wz TOP); C8 (wz BOT)];   (* [comment removed for export] *)
  i_t40  : rw_cells asegs m (TH + 40) [C1 (b8 0)]
}.

End HCW.


Ltac open_ienv E :=
  destruct E as [Etsdi Etp Etsd Ectx Elsan Egot2 Ethr Etid Einit Eafl Ecan Egot Eshb Ehme Ethresh Erms Efill Epart Ehooks Einst1 Einst2
                 Emcs Epsc Ecfu Estk Et40];
  unfold AGOT_VALS in Egot; cbn [map] in Egot; cbn [repeat] in Ehooks.

